use std::io::{self, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};

const MAX_CHUNK_SIZE: u32 = 4096;
const MAX_TOTAL_SIZE: u32 = 1048576; // 1MB
const HEADER_SIZE: usize = 12;

/// Packet format:
/// [4 bytes: magic 0xDEADBEEF]
/// [4 bytes: chunk_length (u32 little-endian)]
/// [4 bytes: offset (u32 little-endian)]
/// [chunk_length bytes: data]

struct SessionBuffer {
    data: Vec<u8>,
    total_received: u32,
    finalized: bool,
}

impl SessionBuffer {
    fn new() -> Self {
        SessionBuffer {
            data: vec![0u8; MAX_TOTAL_SIZE as usize],
            total_received: 0,
            finalized: false,
        }
    }

    /// Validates that the write won't exceed buffer bounds.
    /// Returns the safe copy length after all validation passes.
    fn validate_write(&self, offset: u32, chunk_length: u32) -> Result<usize, &'static str> {
        // Reject oversized individual chunks
        if chunk_length > MAX_CHUNK_SIZE {
            return Err("chunk too large");
        }

        // Reject zero-length writes
        if chunk_length == 0 {
            return Err("empty chunk");
        }

        // Critical bounds check: ensure offset + chunk_length doesn't exceed buffer
        // Use checked arithmetic to prevent integer overflow
        let end_position = match offset.checked_add(chunk_length) {
            Some(end) => end,
            None => return Err("integer overflow in bounds check"),
        };

        // This check ensures the write stays within bounds
        if end_position > MAX_TOTAL_SIZE {
            return Err("write would exceed buffer");
        }

        // Additional safety: verify offset itself is within bounds
        if offset >= MAX_TOTAL_SIZE {
            return Err("offset out of bounds");
        }

        Ok(chunk_length as usize)
    }

    fn write_chunk(&mut self, offset: u32, chunk_data: &[u8], chunk_length: u32) -> Result<(), &'static str> {
        let safe_len = self.validate_write(offset, chunk_length)?;

        if chunk_data.len() < safe_len {
            return Err("insufficient data provided");
        }

        // Perform the copy using validated parameters
        let dst_start = offset as usize;
        let dst_end = dst_start + safe_len;
        self.data[dst_start..dst_end].copy_from_slice(&chunk_data[..safe_len]);

        self.total_received = self.total_received.saturating_add(chunk_length);
        Ok(())
    }
}

fn parse_header(buf: &[u8; HEADER_SIZE]) -> Result<(u32, u32), &'static str> {
    let magic = u32::from_le_bytes([buf[0], buf[1], buf[2], buf[3]]);
    if magic != 0xDEADBEEF {
        return Err("invalid magic");
    }
    let chunk_length = u32::from_le_bytes([buf[4], buf[5], buf[6], buf[7]]);
    let offset = u32::from_le_bytes([buf[8], buf[9], buf[10], buf[11]]);
    Ok((chunk_length, offset))
}

fn handle_client(mut stream: TcpStream, session: Arc<Mutex<SessionBuffer>>) -> io::Result<()> {
    let mut header_buf = [0u8; HEADER_SIZE];

    loop {
        // Read the fixed-size header
        match stream.read_exact(&mut header_buf) {
            Ok(_) => {},
            Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => break,
            Err(e) => return Err(e),
        }

        let (chunk_length, offset) = match parse_header(&header_buf) {
            Ok(v) => v,
            Err(msg) => {
                stream.write_all(b"ERR")?;
                eprintln!("Header parse error: {}", msg);
                continue;
            }
        };

        // Reject oversized chunk_length BEFORE allocating any buffer to prevent
        // memory-exhaustion DoS from attacker-controlled length values.
        if chunk_length == 0 || chunk_length > MAX_CHUNK_SIZE {
            stream.write_all(b"ERR: invalid chunk length\n")?;
            eprintln!("Rejected chunk_length before allocation: {}", chunk_length);
            continue;
        }

        // Read the chunk data (size is now bounded by MAX_CHUNK_SIZE)
        let mut chunk_data = vec![0u8; chunk_length as usize];
        stream.read_exact(&mut chunk_data)?;

        // Write to session buffer with full validation
        let mut sess = session.lock().unwrap();
        match sess.write_chunk(offset, &chunk_data, chunk_length) {
            Ok(_) => {
                stream.write_all(b"OK\n")?;
            }
            Err(msg) => {
                stream.write_all(format!("ERR: {}\n", msg).as_bytes())?;
                eprintln!("Write rejected: {}", msg);
            }
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:9090")?;
    println!("Chunk server listening on :9090");

    for stream in listener.incoming() {
        let stream = stream?;
        let session = Arc::new(Mutex::new(SessionBuffer::new()));
        std::thread::spawn(move || {
            if let Err(e) = handle_client(stream, session) {
                eprintln!("Client error: {}", e);
            }
        });
    }
    Ok(())
}
